/**
 * @file client/src/components/banners/SourceTag.jsx
 * @description Quiet, restrained provenance tag indicating whether a stage or log
 * was fetched from the GitHub Public API or generated by the simulation engine.
 * Strictly adheres to the project honesty rules and Design Reference visual language.
 */

import React from 'react';

export function SourceTag({
  source = 'simulated',
  size = 'sm',
  showDetails = false,
  className = ''
}) {
  const isReal = source === 'real';

  const label = isReal
    ? (showDetails ? 'REAL · GITHUB API' : 'REAL')
    : 'SIMULATED';

  const tooltip = isReal
    ? 'Real metadata fetched via GitHub Public REST API. No code was cloned, built, or executed.'
    : 'Simulated stage execution. No real container or external infrastructure was invoked.';

  return (
    <span
      title={tooltip}
      className={`inline-flex items-center gap-1 font-mono uppercase tracking-[0.12em] rounded-[2px] select-none ${
        size === 'xs'
          ? 'text-[8.5px] px-1 py-0.2'
          : 'text-[9px] px-1.5 py-0.5'
      } ${
        isReal
          ? 'bg-white/5 border border-white/20 text-white/90'
          : 'bg-transparent border border-line text-ink-muted'
      } ${className}`}
    >
      {label}
    </span>
  );
}

export default SourceTag;
